export const GROUPS=['Raven','Ember','Thorn','Ash','Vesper'];
export const PHASES=[
 {name:'Welcome & briefing',time:'19:00',mins:10,type:'brief'},
 {name:'Joining & role reveal',time:'19:10',mins:5,type:'roles'},
 {name:'The Locked Archive',time:'19:15',mins:25,type:'mission',mission:0},
 {name:'Round table I',time:'19:40',mins:10,type:'vote',round:0},
 {name:'The first night',time:'19:50',mins:5,type:'murder',slot:0},
 {name:'The Vault',time:'19:55',mins:20,type:'mission',mission:1,slot:1},
 {name:'Round table II',time:'20:15',mins:10,type:'vote',round:1},
 {name:'Break & night reveal',time:'20:25',mins:10,type:'murder',slot:1},
 {name:'The Last Transmission',time:'20:35',mins:15,type:'mission',mission:2},
 {name:'The final round table',time:'20:50',mins:15,type:'vote',round:2},
 {name:'The truth & awards',time:'21:05',mins:5,type:'final'},
 {name:'Clear up',time:'21:10',mins:5,type:'clear'},
 {name:'Final parade',time:'21:15',mins:15,type:'parade'}
];
export const MISSIONS=[
 {title:'The Locked Archive',description:'Five fragments. One locked box. Piece together the clues with your group and uncover the code before time runs out.',instructions:'Collect the five clue cards from your NCO. Each solved clue gives one digit. Agree on the order, then present your code to the NCO. The NCO checks the physical lock and awards your points.',points:100},
 {title:'The Vault',description:'Trust your judgement. Bank what you have, or risk a little for a greater reward.',instructions:'Solve the first puzzle for 50 points. Choose BANK to keep them, or RISK 25 for a second puzzle worth 75 more. Tell your NCO your decision before attempting the second puzzle. Only the NCO confirms the score.',points:125},
 {title:'The Last Transmission',description:'A broken transmission. A final chance. Combine what each of you heard to find the missing code.',instructions:'Your NCO gives each player a fragment of a fictional radio message. Share fragments within the group, arrange them in order and decode the final phrase. Present it to your NCO for verification.',points:100}
];
export function initial(){return {version:1,phase:0,remaining:600,running:false,deadline:null,joining:true,assigned:false,ended:false,settings:{groups:5,size:10,traitors:2,shields:false,chat:false,decisionMaker:true,sound:false},phases:structuredClone(PHASES),missions:structuredClone(MISSIONS),groups:GROUPS.map((name,id)=>({id,name,score:0,done:false})),players:Array.from({length:50},(_,i)=>({id:i+1,name:`Player ${String(i+1).padStart(2,'0')}`,group:Math.floor(i/10),role:null,status:'Active',connected:true,shield:false})),votes:{},murders:{},messages:[],objectives:{},helps:[],announcements:[{text:'Welcome to the evening. Stay with your group and wait for your NCO’s briefing.',time:'19:00'}],log:[],published:[],lastReveal:null};}
export function record(s,text){s.log.unshift({time:new Date().toLocaleTimeString('en-GB'),text});s.log=s.log.slice(0,300);}
export function getPlayer(s,id){return s.players.find(p=>p.id===Number(id));}
export function active(s,g){return s.players.filter(p=>p.group===Number(g)&&p.status==='Active');}
export function requireThat(test,message){if(!test)throw Error(message);}
export function assign(s){requireThat(!s.assigned,'Roles are already assigned. Reset to run another rehearsal.');s.joining=false;s.groups.forEach(g=>{let people=active(s,g.id);people.forEach(p=>p.role='Faithful');shuffle(people).slice(0,s.settings.traitors).forEach(p=>p.role='Traitor');});s.assigned=true;record(s,'Joining closed. Roles assigned once and released.');}
export function shuffle(a){return [...a].map(x=>({x,r:crypto.getRandomValues(new Uint32Array(1))[0]})).sort((a,b)=>a.r-b.r).map(o=>o.x);}
export function voteKey(s,g){return `${s.phases[s.phase].round??0}:${g}`;}
export function openVote(s,g){requireThat(s.assigned,'Assign roles first.');requireThat(s.phases[s.phase].type==='vote','Move to a round table first.');requireThat(!s.groups[g].done,'This group has caught all its Traitors.');const k=voteKey(s,g);requireThat(!s.votes[k],'This round already has a ballot.');s.votes[k]={status:'open',ballots:{},runoff:false,candidates:null,result:null,revealed:false};record(s,`Voting opened for ${s.groups[g].name}.`);}
export function castVote(s,g,voterId,targetId,manual=false){let v=s.votes[voteKey(s,g)],p=getPlayer(s,voterId),t=getPlayer(s,targetId);requireThat(s.phases[s.phase].type==='vote'&&v?.status==='open','Voting is not open.');requireThat(p&&t&&p.group===Number(g)&&t.group===Number(g),'Vote within your own group.');requireThat(p.status==='Active'&&t.status==='Active','Only active players may vote or receive votes.');requireThat(p.id!==t.id,'You cannot vote for yourself.');requireThat(!v.candidates||v.candidates.includes(t.id),'Choose a runoff candidate.');v.ballots[p.id]=t.id;if(manual)record(s,`NCO recorded a proxy vote for ${p.name}.`);}
export function closeVote(s,g){const v=s.votes[voteKey(s,g)];requireThat(v?.status==='open','No open ballot.');let counts={};Object.values(v.ballots).forEach(id=>counts[id]=(counts[id]||0)+1);v.abstentions=active(s,g).filter(p=>!v.ballots[p.id]).map(p=>p.id);const max=Math.max(0,...Object.values(counts));const tied=Object.keys(counts).filter(id=>counts[id]===max).map(Number);v.tally=counts;v.status=tied.length>1?'tie':'closed';v.tied=tied;v.result=tied.length===1?tied[0]:null;record(s,`${s.groups[g].name}: ballot closed, ${v.abstentions.length} abstention(s). ${tied.length>1?'Tie requires a decision.':tied.length?'Result held privately.':'No votes: no banishment.'}`);}
export function runoff(s,g){const v=s.votes[voteKey(s,g)];requireThat(v?.status==='tie'&&!v.runoff,'Only one runoff is allowed.');v.candidates=v.tied;v.ballots={};v.status='open';v.runoff=true;record(s,`${s.groups[g].name}: runoff opened between tied candidates.`);}
export function randomTie(s,g){const v=s.votes[voteKey(s,g)];requireThat(v?.status==='tie'&&v.runoff,'Complete the runoff first.');v.result=shuffle(v.tied)[0];v.status='closed';record(s,`${s.groups[g].name}: host random draw selected ${getPlayer(s,v.result).name} after a tied runoff.`);}
export function checkGroup(s,g){if(s.assigned&&!active(s,g).some(p=>p.role==='Traitor'))s.groups[g].done=true;}
export function publishBanish(s,g){const v=s.votes[voteKey(s,g)];requireThat(v?.status==='closed'&&v.result&&!v.revealed,'No unpublished banishment.');const p=getPlayer(s,v.result);requireThat(p.status==='Active','Player is already eliminated.');p.status='Banished';v.revealed=true;s.lastReveal={kind:'Banished',id:p.id,name:p.name,group:s.groups[g].name,role:null};s.published.push({...s.lastReveal,time:new Date().toLocaleTimeString('en-GB')});record(s,`${p.name} banished; role reveal awaiting host.`);checkGroup(s,g);}
export function revealRole(s){requireThat(s.lastReveal?.kind==='Banished','Reveal a banishment first.');const p=getPlayer(s,s.lastReveal.id);s.lastReveal.role=p.role;let e=s.published.findLast(e=>e.id===p.id&&e.kind==='Banished');if(e)e.role=p.role;record(s,`${p.name} publicly revealed as ${p.role}.`);}
export function murderKey(g,slot){return `${slot}:${g}`;}
export function propose(s,g,slot,actorId,targetId){requireThat(s.assigned,'Assign roles first.');requireThat([0,1].includes(Number(slot)),'There are two murder opportunities.');const actor=getPlayer(s,actorId),target=getPlayer(s,targetId);requireThat(actor?.status==='Active'&&actor.role==='Traitor'&&actor.group===Number(g),'Only an active Traitor in this group can propose.');requireThat(target?.status==='Active'&&target.role==='Faithful'&&target.group===Number(g),'Choose an active Faithful in your group.');const key=murderKey(g,slot);const m=s.murders[key]??={choices:{},confirmed:false,published:false,mode:Number(slot)===1?'secret':'standard'};requireThat(!m.confirmed&&!m.published,'This opportunity has already been resolved.');m.choices[actorId]=Number(targetId);m.target=Number(targetId);}
export function confirmMurder(s,g,slot,success=true){const m=s.murders[murderKey(g,slot)];requireThat(m&&!m.confirmed&&!m.published,'No unresolved attempt.');const p=getPlayer(s,m.target);requireThat(p?.status==='Active'&&p.role==='Faithful'&&p.group===Number(g),'Target is no longer eligible.');requireThat(active(s,g).some(p=>p.role==='Traitor'),'No active Traitors remain to complete this attempt.');const choices=Object.values(m.choices);const disagree=new Set(choices).size>1;requireThat(!disagree||s.settings.decisionMaker,'Traitors disagree. Resolve the choice or enable the designated decision maker.');if(disagree){const leader=active(s,g).filter(p=>p.role==='Traitor').sort((a,b)=>a.id-b.id)[0];requireThat(m.choices[leader.id],'The designated decision maker must choose first.');m.target=m.choices[leader.id];}const victim=getPlayer(s,m.target);requireThat(victim.status==='Active','Target is no longer active.');m.confirmed=true;m.blocked=success&&s.settings.shields&&victim.shield;m.success=success&&!m.blocked;m.reason=!success?'Objective not completed':m.blocked?'Shield protection':'Confirmed';record(s,`${s.groups[g].name}, opportunity ${Number(slot)+1}: ${m.reason}. Outcome held privately.`);}
export function publishMurder(s,g,slot){const m=s.murders[murderKey(g,slot)];requireThat(m?.confirmed&&!m.published,'Confirm the outcome before publishing.');m.published=true;const p=getPlayer(s,m.target);const kill=m.success&&p.status==='Active';if(kill)p.status='Murdered';s.lastReveal={kind:kill?'Murdered':'No murder',id:kill?p.id:null,name:kill?p.name:'Everyone returns',group:s.groups[g].name,role:null};s.published.push({...s.lastReveal,time:new Date().toLocaleTimeString('en-GB')});record(s,`${s.groups[g].name}: ${kill?p.name+' murdered':m.success?'target already eliminated; no replacement victim':'no murder'} publicly released.`);}
export function finish(s){requireThat(s.assigned,'Assign roles before revealing winners.');requireThat(!Object.values(s.murders).some(m=>m.confirmed&&!m.published),'Publish confirmed murder outcomes before ending the game.');s.ended=true;s.running=false;s.deadline=null;record(s,'Host ended the game and released all roles and group winners.');}
export function results(s){return s.groups.map(g=>({...g,winner:active(s,g.id).some(p=>p.role==='Traitor')?'Traitors':'Faithful'}));}
export function publicData(s){return {title:'2427: Trust No One',phase:s.phases[s.phase],remaining:s.remaining,running:s.running,deadline:s.deadline,mission:s.phases[s.phase].type==='mission'?s.missions[s.phases[s.phase].mission]:null,groups:s.groups.map(g=>({name:g.name,score:g.score})),announcements:s.announcements,published:s.published,lastReveal:s.lastReveal,players:s.players.map(p=>({id:p.id,name:p.name,group:s.groups[p.group].name,status:p.status,...(s.ended?{role:p.role}:{})})),ended:s.ended,results:s.ended?results(s):null,updated:Date.now()};}
